EXEC pkg_market_import.process_batch(:b_capital)
DECLARE s VARCHAR2(16); n NUMBER; BEGIN
  SELECT batch_status, imported_count INTO s, n FROM etl_batches WHERE batch_id = :b_capital;
  IF s <> 'COMPLETED' OR n <> 36 THEN raise_application_error(-20993, 'capital batch ' || s || ', imported ' || n || ' of 36'); END IF;
END;
