EXEC pkg_market_import.seal_batch(:b_prices)
COMMIT;
EXEC pkg_market_import.process_batch(:b_prices)
DECLARE s VARCHAR2(16); n NUMBER; BEGIN
  SELECT batch_status, imported_count INTO s, n FROM etl_batches WHERE batch_id = :b_prices;
  IF s <> 'COMPLETED' OR n <> 2991 THEN raise_application_error(-20993, 'prices batch ' || s || ', imported ' || n || ' of 2991'); END IF;
END;
